concepts.code:
user  nginx;
worker_processes  auto;              # main context
error_log  /var/log/nginx/error.log warn;

events {
    worker_connections  1024;
}

http {
    include       /etc/nginx/mime.types;
    default_type  application/octet-stream;   # type for unknown files
    sendfile      on;
    add_header    X-Frame-Options DENY;          # inherited by servers...

    server {
        listen 80;
        location / {
            root /usr/share/nginx/html;          # ...and by this location
        }
    }
    include /etc/nginx/conf.d/*.conf;            # more server blocks
}

server {
    listen 80 default_server;        # catch-all for unknown Host headers
    server_name _;
    return 444;                      # close the connection, send nothing
}

server {
    listen 80;
    server_name example.com www.example.com;
    root /var/www/example;
}

server {
    listen 80;
    server_name *.shop.example.com;   # any subdomain of shop.example.com
    root /var/www/shop;
}
# curl -H 'Host: www.example.com' http://127.0.0.1/  -> /var/www/example
# curl -H 'Host: other.org' http://127.0.0.1/        -> connection closed

server {
    listen 80;
    server_name app.example.com;
    root /var/www/app/dist;             # /about -> /var/www/app/dist/about
    index index.html;

    location / {
        try_files $uri $uri/ /index.html;   # single-page app fallback
    }

    location /assets/ {
        expires 1y;                     # names change each build: cache long
        access_log off;
    }

    location /downloads/ {
        alias /srv/files/;              # /downloads/a.zip -> /srv/files/a.zip
    }
}

server {
    listen 80;
    location = / { return 200 "exact root\n"; }
    location / { return 200 "prefix /\n"; }
    location /images/ { return 200 "prefix images\n"; }
    location ^~ /static/ { return 200 "static, no regex\n"; }
    location ~* \.(png|jpg)$ { return 200 "regex image\n"; }
}
# GET /              -> exact root
# GET /about         -> prefix /
# GET /images/a.png  -> regex image   (regex beats a normal prefix)
# GET /static/a.png  -> static, no regex   (^~ stops regex search)
# GET /images/a.txt  -> prefix images

server {
    listen 80;
    server_name example.com;

    location /api/ {
        proxy_pass http://127.0.0.1:8000/;      # /api/users -> /users
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Forwarded-For   $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_read_timeout 30s;
    }

    location /admin/ {
        proxy_pass http://127.0.0.1:9000;       # /admin/x -> /admin/x
    }
}
# curl -i http://example.com/api/health
# HTTP/1.1 502 Bad Gateway   <- when nothing listens on :8000

http {
    log_format json escape=json '{'
        '"time":"$time_iso8601","ip":"$remote_addr",'
        '"req":"$request","status":$status,"bytes":$body_bytes_sent,'
        '"rt":$request_time,"urt":"$upstream_response_time",'
        '"upstream":"$upstream_addr","id":"$request_id"}';

    access_log /var/log/nginx/access.json json buffer=32k flush=5s;
    error_log  /var/log/nginx/error.log warn;

    server {
        listen 80;
        location = /healthz { access_log off; return 200 "ok\n"; }
        location / {
            proxy_set_header X-Request-ID $request_id;
            proxy_pass http://127.0.0.1:8000;
        }
    }
}

server {
    listen 80;
    server_name example.com;
    location /.well-known/acme-challenge/ { root /var/www/certbot; }
    location / { return 301 https://$host$request_uri; }
}

server {
    listen 443 ssl;
    http2 on;
    server_name example.com;

    ssl_certificate     /etc/letsencrypt/live/example.com/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/example.com/privkey.pem;
    ssl_protocols       TLSv1.2 TLSv1.3;
    ssl_session_cache   shared:SSL:10m;
    add_header Strict-Transport-Security "max-age=31536000" always;

    location / { proxy_pass http://127.0.0.1:8000; }
}

map $uri $new_uri {                       # in http context
    /old-pricing   /pricing;
    /blog/2023     /blog/archive/2023;
}

server {
    listen 80;
    server_name www.example.com;
    return 301 https://example.com$request_uri;    # canonical host
}

server {
    listen 80;
    server_name example.com;
    if ($new_uri) { return 301 $new_uri; }         # table-driven redirects
    rewrite ^/users/(\d+)$ /profile?id=$1 last;    # internal rewrite
    location = /profile { return 200 "profile $arg_id\n"; }
}
# GET /users/42 -> profile 42

upstream app {
    least_conn;
    server 10.0.0.11:8000 max_fails=3 fail_timeout=30s;
    server 10.0.0.12:8000 max_fails=3 fail_timeout=30s;
    server 10.0.0.13:8000 backup;          # only when both are down
    keepalive 32;                          # idle connections kept per worker
}

server {
    listen 80;
    location / {
        proxy_pass http://app;
        proxy_http_version 1.1;            # needed for upstream keepalive
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_next_upstream error timeout http_502;
        proxy_next_upstream_tries 2;
    }
}

http {
    server_tokens off;
    server {
        listen 80;
        client_max_body_size 10m;
        add_header X-Content-Type-Options nosniff always;
        add_header Referrer-Policy strict-origin-when-cross-origin always;

        location /admin/ {
            satisfy any;                       # office IP OR password
            allow 203.0.113.0/24;
            deny  all;
            auth_basic           "Admin";
            auth_basic_user_file /etc/nginx/.htpasswd;
            proxy_pass http://127.0.0.1:8000;
        }
        location = /metrics {
            allow 10.0.0.0/8;                  # internal scrapers only
            deny  all;
            proxy_pass http://127.0.0.1:9100;
        }
    }
}

http {
    proxy_cache_path /var/cache/nginx levels=1:2 keys_zone=app_cache:10m
                     max_size=1g inactive=60m use_temp_path=off;
    server {
        listen 80;
        location / {
            proxy_pass http://127.0.0.1:8000;
            proxy_cache app_cache;
            proxy_cache_valid 200 301 10m;
            proxy_cache_valid 404 1m;
            proxy_cache_use_stale error timeout updating http_502 http_503;
            proxy_cache_background_update on;
            proxy_cache_lock on;
            proxy_cache_bypass $cookie_session;    # logged-in users skip cache
            proxy_no_cache     $cookie_session;
            add_header X-Cache-Status $upstream_cache_status;
        }
    }
}
# curl -sI localhost/products | grep X-Cache   -> MISS, then HIT

http {
    limit_req_zone  $binary_remote_addr zone=api:10m   rate=10r/s;
    limit_req_zone  $binary_remote_addr zone=login:10m rate=5r/m;
    limit_conn_zone $binary_remote_addr zone=perip:10m;
    limit_req_status 429;

    server {
        listen 80;
        location /api/ {
            limit_req zone=api burst=20 nodelay;   # bursts OK, abuse rejected
            proxy_pass http://127.0.0.1:8000;
        }
        location = /login {
            limit_req zone=login burst=3;          # excess queued, then 429
            proxy_pass http://127.0.0.1:8000;
        }
        location /downloads/ {
            limit_conn perip 2;                    # 2 concurrent downloads
        }
    }
}

map $http_upgrade $connection_upgrade {      # http context
    default upgrade;
    ''      close;
}

server {
    listen 80;
    location /ws/ {
        proxy_pass http://127.0.0.1:9000;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $connection_upgrade;
        proxy_read_timeout 1h;                 # idle sockets stay open
    }
    location /events {                         # Server-Sent Events
        proxy_pass http://127.0.0.1:8000;
        proxy_buffering off;                   # flush each event immediately
        proxy_read_timeout 10m;
    }
}

worker_processes auto;            # one per core
worker_rlimit_nofile 65535;       # fd limit per worker
worker_shutdown_timeout 30s;      # cap graceful shutdown on reload

events {
    worker_connections 16384;     # clients + upstream connections, per worker
}

http {
    server {
        listen 80 reuseport;      # per-worker listening sockets
        location / { return 200 "ok\n"; }
    }
}
# ps -o pid,user,cmd -C nginx
#   PID USER   CMD
#   812 root   nginx: master process /usr/sbin/nginx
#   813 nginx  nginx: worker process
#   814 nginx  nginx: worker process

map $http_x_api_key $limit_key {        # http context
    default         $binary_remote_addr;  # anonymous: limit by IP
    "~^key_"        $http_x_api_key;      # API clients: limit by key
}
map $status $loggable {                   # don't log 2xx/3xx
    ~^[23]  0;
    default 1;
}
limit_req_zone $limit_key zone=api:10m rate=20r/s;

server {
    listen 80;
    access_log /var/log/nginx/errors.log combined if=$loggable;
    location /api/ {
        limit_req zone=api burst=40 nodelay;
        deny all;
        return 200 "ok\n";     # still served: return runs before access checks
    }
}

http {
    sendfile    on;
    tcp_nopush  on;
    keepalive_timeout 30s;
    open_file_cache          max=10000 inactive=30s;
    open_file_cache_valid    60s;

    gzip            on;
    gzip_comp_level 5;
    gzip_min_length 1024;
    gzip_types      text/css application/javascript application/json image/svg+xml;
    gzip_vary       on;                 # Vary: Accept-Encoding for caches

    proxy_buffer_size 16k;              # response headers
    proxy_buffers     16 16k;           # body buffers per connection

    server {
        listen 80;
        location /assets/ { root /var/www; gzip_static on; expires 1y; }
    }
}
